  Lemma lit_upgrade_acc8 : forall m, ACONST m -> accessible m ALIT_UPGRADE 8.
  Proof. intros m AC. apply (ACONST_gbody_accessible m ALIT_UPGRADE 8 AC). vm_compute. reflexivity. Qed.

  (* [comment removed for export] *)
  Lemma sext8_small : forall j, 0 <= j < 128 -> Z.shiftr (bv_signed (Z_to_bv 64 (Z.shiftl j 56))) 56 = j.
  Proof.
    intros j Hj. rewrite Z.shiftl_mul_pow2 by lia. rewrite bv_signed_small by (rewrite unsigned_lit; lia).
    rewrite unsigned_lit by lia. rewrite Z.shiftr_div_pow2 by lia. rewrite Z.div_mul by lia. reflexivity.
  Qed.
