(* [comment removed for export] *)
Lemma ka_fast : forall (k j : nat) (Q : machine_state -> Prop) rax spx gp tp t1 t2 s0 s1 a0 a1 a3 a6 s2 s4 s5 s6 s7 s8 s9 s11 t5 t6
    (F : bvmap 5 word) fc (m1 : mem) (vp D : Z) (vbs : list byte) (T4 T3 A2 A7 : Z),
  (10 - j = k)%nat -> (j <= 10)%nat ->
  bytes_at asegs m1 vp vbs -> accessible m1 vp (Z.of_nat (length vbs)) -> mem_inv asegs m1 -> ACONST m1 ->
  vp <= D -> D + 10 <= vp + Z.of_nat (length vbs) -> vp + Z.of_nat (length vbs) < 2^64 -> 0 < vp ->
  dof_cont3 Q 0xd1ddc rax spx gp tp s0 s1 (wz 512) s2 (wz 7) s4 s5 s6 s7 s8 s9 (wz ASHADOW_BASE) s11 F fc m1 ->
  dof_cont Q 0xd1df8 rax spx gp tp s0 s1 s2 (wz 7) s4 s5 s6 s7 s8 s9 (wz ASHADOW_BASE) s11 F fc m1 ->
  T4 = ALIT_KEEPALIVE + Z.of_nat j -> T3 = D + Z.of_nat j -> A2 = 10 - Z.of_nat j -> A7 = Z.of_nat j - 10 ->
  evt asegs Q (MS (mkR rax spx gp tp (wz ALIT_KEEPALIVE) t1 t2 s0 s1 a0 a1 (wz A2) a3 (wz D) (wz 10) a6 (wz A7)
                       s2 (wz 7) s4 s5 s6 s7 s8 s9 (wz ASHADOW_BASE) s11 (wz T3) (wz T4) t5 t6)
