    (F : bvmap 5 word) fc (m1 : mem) (vp D : Z) (vbs : list byte) (T1 T0 A2 A6 : Z),
  (5 - j = k)%nat -> (j <= 5)%nat ->
  bytes_at asegs m1 vp vbs -> accessible m1 vp (Z.of_nat (length vbs)) -> mem_inv asegs m1 -> ACONST m1 ->
  vp <= D -> D + 5 <= vp + Z.of_nat (length vbs) -> vp + Z.of_nat (length vbs) < 2^64 -> 0 < vp ->
